float hash12(vec2 p) // https://www.shadertoy.com/view/4djSRW Hash without Sine by Dave_Hoskins
{
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

#define pi 3.1415926
#define tau (pi+pi)

mat3 yaw_pitch_roll(float yaw, float pitch, float roll)
{
    mat3 R = mat3(vec3(cos(yaw), sin(yaw), 0.0), vec3(-sin(yaw), cos(yaw), 0.0), vec3(0.0, 0.0, 1.0));
    mat3 S = mat3(vec3(1.0, 0.0, 0.0), vec3(0.0, cos(pitch), sin(pitch)), vec3(0.0, -sin(pitch), cos(pitch)));
    mat3 T = mat3(vec3(cos(roll), 0.0, sin(roll)), vec3(0.0, 1.0, 0.0), vec3(-sin(roll), 0.0, cos(roll)));

    return R * S * T;
}

// https://mathworld.wolfram.com/RodriguesRotationFormula.html
// https://www.euclideanspace.com/maths/geometry/rotations/conversions/angleToMatrix/index.htm
mat3 rotation(vec2 cs, vec3 k) // https://www.shadertoy.com/view/mt3BRB rotate from vector to vector, by rodrigues' rotation (jt)
{
    cs = normalize(cs);
    k = normalize(k);
    float t = 1.0 - cs.x;
    return
        mat3
        (
            vec3(t*k.x*k.x+cs.x,t*k.x*k.y+k.z*cs.y,t*k.x*k.z-k.y*cs.y),
            vec3(t*k.x*k.y-k.z*cs.y,t*k.y*k.y+cs.x,t*k.y*k.z+k.x*cs.y),
            vec3(t*k.x*k.z+k.y*cs.y,t*k.y*k.z-k.x*cs.y,t*k.z*k.z+cs.x)
        );
}

mat3 rotation(vec3 src, vec3 dst) // https://www.shadertoy.com/view/mt3BRB rotate from vector to vector, by rodrigues' rotation (jt)
{
    src = normalize(src);
    dst = normalize(dst);
    float d = dot(src, dst);
    vec3 k = cross(src, dst);
    return rotation(vec2(d, length(k)), k);
}

#define DIST_MAX 1000.0

#define MAX_RAY_STEPS 64

float terrain(int n, ivec2 v) // https://www.shadertoy.com/view/43syR7 voxel terrain (jt)
{
    int m = 1 << n;
    ivec2 v0 = v & ~(m-1); // clear n lower bits
    v -= v0; // n lower bits

    float h00 = hash12(vec2(v0 + ivec2(0,0)));
    float h01 = hash12(vec2(v0 + ivec2(m,0)));
    float h10 = hash12(vec2(v0 + ivec2(0,m)));
    float h11 = hash12(vec2(v0 + ivec2(m,m)));

    //return hash12(vec2(v0));
    //return (float(m-v)*h00+float(m)*h01)/float(m);
    //return mix(h00,h01,float(v)/float(m));
    vec2 q = vec2(v)/vec2(m-1);
    return mix(mix(h00,h01,q.x),mix(h10,h11,q.x),q.y);
}

float terrain_iterated(int n, ivec2 v) // https://www.shadertoy.com/view/43syR7 voxel terrain (jt)
{
    float h = 0.0;
    for(int i = 1; i < n; i++)
    {
        h += terrain(i, v) * float(1<<i);
    }
    return h;
}

float height(ivec2 v)
{
    return terrain(2, v) * 2.0; // simple but fast
    return terrain_iterated(4, v)/4.0-1.0; // more complex but slow
}

vec3 height_normal(ivec2 p)
{
    return // symmetric normal -1,+1 (better approximation that the asymmetric variant 0,1)
        normalize
        (
            vec3
            (
                height(p - ivec2(1,0)) - height(p + ivec2(1,0)),
                height(p - ivec2(0,1)) - height(p + ivec2(0,1)),
                2.0
            )
        );
}

vec4 heights(ivec2 v) // https://www.shadertoy.com/view/4cBfRR terrain approximation with tiles (jt)
{
    ivec2 o00 = ivec2(0,0);
    ivec2 o10 = ivec2(1,0);
    ivec2 o01 = ivec2(0,1);
    ivec2 o11 = ivec2(1,1);
    float h00 = height(v.xy+o00);
    float h10 = height(v.xy+o10);
    float h01 = height(v.xy+o01);
    float h11 = height(v.xy+o11);

    return vec4(h00,h10,h01,h11);
}

float height_interpolated(vec2 v)
{
    vec4 H = heights(ivec2(floor(v)));
    return
        mix
        (
            mix(H[0],H[1],fract(v.x)),
            mix(H[2],H[3],fract(v.x)),
            fract(v.y)
        );
}

vec3 force_normal_up(vec3 n)
{
    return n.z < 0.0 ? -n : +n;
}

vec4 force_normal_up(vec4 q)
{
    return vec4(force_normal_up(q.xyz),q.w);
}

vec4 combine(vec4 a, vec4 b)
{
    if(a.w < b.w) return a;
    return b;
}

vec4 sphere_intersection(vec3 ro, vec3 rd, float ra) // adapted from https://iquilezles.org/articles/intersectors
{
    float b = dot( ro, rd );
    float c = dot( ro, ro ) - ra*ra;
    float h = b*b - c;
    if( h<0.0 ) return vec4(-rd, DIST_MAX); // no intersection
    h = sqrt( h );
    float t = -b-h;
    if(t < 0.0) return vec4(-rd, DIST_MAX); // no intersection
    return vec4(normalize(ro+rd*t), t);
}

vec4 box_intersection(vec3 ro, vec3 rd, vec3 sz) // adapted from https://iquilezles.org/articles/intersectors
{
    vec3 m = 1.0/rd;
    vec3 n = m*ro;
    vec3 k = abs(m)*sz;
    vec3 t1 = -n - k;
    vec3 t2 = -n + k;
    float tN = max(max( t1.x, t1.y), t1.z);
    float tF = min(min( t2.x, t2.y), t2.z);
    if( tN>tF || tF<0.0) return vec4(-rd, DIST_MAX); // no intersection
    vec3 norm = (tN>0.0) ? step(vec3(tN),t1) : // ro ouside the box
                                step(t2,vec3(tF));  // ro inside the box
    norm *= -sign(rd);
    return vec4(norm, tN);
}

vec4 triangle_intersection(vec3 ro, vec3 rd, vec3 v0, vec3 v1, vec3 v2) // modified https://iquilezles.org/articles/intersectors/
{
    vec3 v1v0 = v1 - v0;
    vec3 v2v0 = v2 - v0;
    vec3 rov0 = ro - v0;
    vec3  n = cross( v1v0, v2v0 );
    vec3  q = cross( rov0, rd );
    float d = 1.0/dot( rd, n );
    float u = d*dot( -q, v2v0 );
    float v = d*dot(  q, v1v0 );
    float t = d*dot( -n, rov0 );
    if( u<0.0 || v<0.0 || (u+v)>1.0 ) return vec4(-rd, DIST_MAX);
    return vec4(normalize(n), t);
}

vec4 terrain_approximation_with_tiles(vec3 ro, vec3 rd, ivec2 v) // https://www.shadertoy.com/view/4cBfRR terrain approximation with tiles (jt)
{
    vec2 p = vec2(v);
    ivec2 o00 = ivec2(0,0);
    ivec2 o10 = ivec2(1,0);
    ivec2 o01 = ivec2(0,1);
    ivec2 o11 = ivec2(1,1);
    vec2 o = vec2(o00 + o10 + o01 + o11) / 4.0; // for crisp heightmap
    float h00 = height(v.xy+o00);
    float h10 = height(v.xy+o10);
    float h01 = height(v.xy+o01);
    float h11 = height(v.xy+o11);
    float h = (h00 + h01 + h10 + h11) / 4.0; // for crisp heightmap
    vec3 q00 = vec3(o00,h00);
    vec3 q01 = vec3(o01,h01);
    vec3 q10 = vec3(o10,h10);
    vec3 q11 = vec3(o11,h11);
    vec3 q = vec3(o,h);
    vec4 result =
        combine
        (
            combine
            (
                triangle_intersection(ro, rd, q00, q01, q),
                triangle_intersection(ro, rd, q01, q11, q)
            ),
            combine
            (
                triangle_intersection(ro, rd, q11, q10, q),
                triangle_intersection(ro, rd, q10, q00, q)
            )
        );
#ifdef SMOOTH_NORMALS
    vec2 dst = (ro+rd*result.w).xy;
    result.xyz =
        normalize
        (
            mix
            (
                mix(height_normal(v.xy+o00),height_normal(v.xy+o10),dst.x),
                mix(height_normal(v.xy+o01),height_normal(v.xy+o11),dst.x),
                dst.y
            )
        );
#else
    //result.xyz = height_normal(p+o);
    result.xyz = force_normal_up(result.xyz);
#endif
    return result;
}

struct result
{
    vec3 normal;
    float dist;
    vec3 color;
};

result combine(result a, result b)
{
    //return a.dist < b.dist ? a : b; // ??? why doesn't this compile ???
    if(a.dist < b.dist)
        return a;
    return b;
}

float checker(vec2 p)
{
    return step(0.0,sin(p.x*tau)*sin(p.y*tau));
}

float checker(vec3 p)
{
    return step(0.0,sin(p.x*tau)*sin(p.y*tau)*sin(p.z*tau));
}

float line_segment_distance(vec3 p, vec3 a, vec3 b) // https://iquilezles.org/articles/distfunctions/
{
    vec3 pa = p - a, ba = b - a;
    float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
    return length(pa - ba*h);
}

float box_distance(vec3 p, vec3 b) // https://iquilezles.org/articles/distfunctions/
{
    vec3 q = abs(p) - b;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float box_distance(vec3 p, vec3 v0, vec3 v1, float r)
{
    vec3 c = (v1+v0)/2.0;
    vec3 e = (v1-v0)/2.0;
    return box_distance(p - c, e - r) - r;
}

float cylinder_distance(vec3 p, float r, float h) // modified https://iquilezles.org/articles/distfunctions/
{
    vec2 d = abs(vec2(length(p.xy),p.z)) - vec2(r,h);
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float frame_distance(vec3 p, vec3 b, float e) // https://iquilezles.org/articles/distfunctions/
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;
  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0))+min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0))+min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0))+min(max(q.x,max(q.y,p.z)),0.0));
}

float frame_distance(vec3 p, vec3 v0, vec3 v1, float d)
{
    vec3 c = (v1+v0)/2.0;
    vec3 e = (v1-v0)/2.0;
    return frame_distance(p - c, e, d);
}

float ortho_circle_flower_distance(int n, vec2 p) // https://www.shadertoy.com/view/dldBWl orthogonal circle flower sdf, 2023 jt
{
    n = 2*n+1; // n must be odd
    float slice = pi/float(n);

    p.x = abs(p.x); // mirror horizontally
    float r = (p.y*p.y+2.0*p.y+p.x*p.x+1.0)/(2.0*p.x); // calculate radius of circular arc leaf passing through this point

    // equidistant circle segment endpoints on unit circle
    float r0 = tan(floor(atan(r)/slice)*slice); // to angle then quantize then to length
    float r1 = tan( ceil(atan(r)/slice)*slice); // to angle then quantize then to length

    // circle center
    vec2 c0 = vec2(r0,-1); // lower leaf
    vec2 c1 = vec2(r1,-1); // upper leaf

    // endpoints
    float mu = atan(p.x,p.y);
    mu = (floor(mu/slice/2.0)+0.5)*slice*2.0;
    vec2 c = vec2(sin(mu),cos(mu));

    return
        //length(p) < 1.0; // approximate
        dot(p, c) < 1.0 // thanks to tdhooper for fixing remaining discontinuities by changing length(p) < 1.0 to dot(p, c) < 1.0 (turns circle into polygon)
        ?
        min(abs(length(p-c0)-r0),abs(length(p-c1)-r1)) // circular arc leafs
        :
        length(p-c); // leaf endpoints
}

float ortho_circle_flower_distance(int m, int n, vec3 p) // https://www.shadertoy.com/view/dtGBDz orthogonal circles grassy plant (jt)
{
    float phi = round(atan(p.y,p.x)/(2.0*pi/float(m)))*(2.0*pi/float(m)); // polar & quantize
    p.xy = mat2(cos(phi),-sin(phi),sin(phi),cos(phi))*p.xy;
    return length(vec2(ortho_circle_flower_distance(n, vec2(p.xz)),p.y));
}

#define MAX_MARCH_STEPS 100u
#define EPSILON 0.001
#define MARGIN 0.01

float CYLINDER_Z(ivec2 tile, vec3 p)
{
    float r = 0.1;
    float h = hash12(vec2(tile)) + 0.5;
    return cylinder_distance(p - vec3(0.5,0.5, h), 0.5-r-MARGIN, h-r)-r;
    //return cylinder_distance(p-vec3(0,0,0.25), 0.5-r-MARGIN, 0.75-r)-r;
    //float h = hash12(vec2(tile));
   // return cylinder_distance(p-vec3(0,0,0.5-h), 0.5-r-MARGIN, h-r)-r;
}

float FRAME(ivec2 tile, vec3 p)
{
    vec3 n = height_normal(tile);
    mat3 R = rotation(n,vec3(0,0,1));
    float h = mix(0.25,0.5,hash12(vec2(tile)));
    return frame_distance(p, vec3(0)+MARGIN, vec3(1,1,h+0.5)-MARGIN, 0.02);
    //return frame_distance(R*(p-vec3(0.5,0.5,h)), vec3(0.3,0.3,h)-MARGIN, 0.02);
}

float PLANT(ivec2 tile, vec3 p)
{
    float r = 0.01;
    return ortho_circle_flower_distance(5,3,(p - 0.5)*2.)/2.-r;
}

float BOX(ivec2 tile, vec3 p)
{
    vec3 n = height_normal(tile);
    mat3 R = rotation(n,vec3(0,0,1));
    float h = 0.05;//hash12(vec2(tile));
    //return box_distance(R*(p-vec3(0.5,0.5,0))-vec3(0,0,h), vec3(0.4,0.4,h)-MARGIN);
    return box_distance(R*(p-vec3(0.5,0.5,h)), vec3(0.4,0.4,h)-MARGIN);
}

float PIPE(ivec2 tile, vec3 p)
{
    float h0 = height_interpolated(vec2(tile)+0.5-vec2(0,0.5)); // height at center
    float height = height_interpolated(vec2(tile)+0.5); // height at center
    float h1 = height_interpolated(vec2(tile)+0.5+vec2(0,0.5)); // height at center
    return line_segment_distance(p, vec3(0.5,0,0.5+float(h0)), vec3(0.5,1,0.5+float(h1))) - 0.25;
}

// https://www.shadertoy.com/view/M33cRl raytrace terrain raymarch object by jt
// plugin to translate ray-marching to ray-tracing
// (uses iq's numerical tetrahedron normal approximation)
// emulate passing function as argument (jt), vec4 RESULT xyz is normal, w is distance, returns sky if distance out of range [t0, t1]
#define MARCH(RESULT, TILE, MAP, RO, RD, T0, T1) \
do \
{ \
    ivec2 tile = TILE; \
    vec3 ro = RO, rd = RD; \
    float t0 = T0, t1 = T1; \
    float h; uint i; \
    for(RESULT.w = t0, i = 0u; RESULT.w < t1 && i < MAX_MARCH_STEPS; i++) \
    { \
        vec3 p = ro + rd * RESULT.w; \
        h = MAP(tile, p); \
        if(h < EPSILON) break; \
        RESULT.w += h; \
    } \
    if(RESULT.w >= tmin && RESULT.w <= tmax) \
    { \
        vec3 p = ro + rd * RESULT.w; \
        const float h = 0.0001; \
        const vec2 k = vec2(1,-1); \
        RESULT.xyz = \
            normalize \
            ( \
                k.xyy*MAP(tile, p + k.xyy*h) + \
                k.yyx*MAP(tile, p + k.yyx*h) + \
                k.yxy*MAP(tile, p + k.yxy*h) + \
                k.xxx*MAP(tile, p + k.xxx*h) \
            ); \
    } \
    else \
    { \
        RESULT = vec4(-rd, DIST_MAX); \
    } \
} \
while(false) \
// END MARCH

result trace(vec3 ray_pos_orig, vec3 ray_dir_orig)
{
    result content = result(-ray_dir_orig, DIST_MAX, vec3(0)); // sky sphere
    vec2 ray_pos_flat = ray_pos_orig.xy;
    vec2 ray_dir_flat = ray_dir_orig.xy;
    // initialization from https://www.shadertoy.com/view/4dX3zl Branchless Voxel Raycasting by fb39ca4 implementing https://lodev.org/cgtutor/raycasting.html
    ivec2 tile = ivec2(floor(ray_pos_flat));
    // decompose ray direction into reciprocal absolute ray direction and sign (-1,+1)
    vec2 delta_dist = 1.0 / abs(ray_dir_flat); // reciprocal absolute ray direction
    ivec2 ray_step = ivec2(sign(ray_dir_flat)); // sign of ray direction
    // initial distances to nearest walls by dimension:
    //     calculate ray position in relation to tile origin
    //     (requires adding one half because tile origin is floor of ray position)
    //     adjust sign according to ray direction
    //     because tile has size 1 and we start in the middle wall is located at 0.5 (sign depends on ray direction)
    //     divide by ray direction (to get distance with respect to ray)
    vec2 side_dist = (sign(ray_dir_flat) * (vec2(tile) - ray_pos_flat) + (sign(ray_dir_flat) * 0.5) + 0.5) * delta_dist; // initial distances to nearest walls by dimension
    bvec2 nearest = bvec2(0); // component is true if nearest wall in that dimension
    for (int i = 0; i < MAX_RAY_STEPS; i++)
    {
        bool even = ((tile.x ^ tile.y) & 1) == 0;
        float flip = even?-1.0:+1.0;

        float tmin = length(vec2(nearest) * (side_dist - delta_dist)); // calculate distance to intersection point assuming ray_dir normalized

        // core from https://www.shadertoy.com/view/4dX3zl Branchless Voxel Raycasting by fb39ca4 implementing https://lodev.org/cgtutor/raycasting.html
        bvec2 nearest_next = lessThanEqual(side_dist.xy, side_dist.yx); // component is true if nearest wall in that dimension
        vec2 side_dist_next = side_dist + vec2(nearest_next) * delta_dist; // update distances to nearest walls by dimension
        ivec2 tile_next = tile + ivec2(vec2(nearest_next)) * ray_step; // step to next tile in direction of nearest wall
        float tmax = length(vec2(nearest_next) * (side_dist_next - delta_dist)); // calculate distance to intersection point assuming ray_dir normalized

        if(all(lessThan(abs(tile - ivec2(floor(ray_pos_flat))), ivec2(VISION_LIMIT))))
        {
            vec3 local = ray_pos_orig - vec3(tile, 0);
#ifdef WATER
            float water_level = 1.0;
            {
                float t = (water_level - ray_pos_orig.z)/ray_dir_orig.z;
                vec3 n = vec3(0,0,1);

                if(t > tmin && t < tmax)
                {
                    vec3 dst = local+ray_dir_orig*t;
                    vec3 color = vec3(0,0,1);
                    content = combine(content, result(n, t, color));
                }
            }
#endif
            {
                vec4 nd = terrain_approximation_with_tiles(local, ray_dir_orig, tile);
                if(nd.w > tmin && nd.w < tmax)
                {
                    vec3 color = vec3(0,1,0);
                    //vec3 color = vec3((local+ray_dir_flat*nd.w).xy,0);
                    //vec3 color = vec3(local+ray_dir_flat*nd.w);
                    vec3 dst = local+ray_dir_orig*nd.w;
                    color *= mix(vec3(0.5),vec3(0.75),vec3(checker(dst.xy)));
                    content = combine(content, result(nd.xyz, nd.w, color));
                }

                float rnd = hash12(vec2(tile)*123.0);
#ifdef PIPELINE
                if(tile.x == 0)
                {
                    vec4 nd; MARCH(nd, tile, PIPE, local, ray_dir_orig, tmin, tmax);
                    if(nd.w < DIST_MAX)
                    {
                        //vec3 color = vec3(0.05,0,0.5);
                        //vec3 color = vec3(1.0,0.2,0);
                        vec3 color = vec3(1);
                        content = combine(content, result(nd.xyz, nd.w, color));
                    }
                }
                else
#endif
                if(rnd < 0.1)
                {
                    //float height = height(tile);
                    float height = height_interpolated(vec2(tile)+0.5); // height at center
                    vec4 nd; MARCH(nd, tile, FRAME, ray_pos_orig-vec3(vec2(tile.xy),height), ray_dir_orig, tmin, tmax);
                    if(nd.w > tmin && nd.w < tmax)
                    {
                        vec3 color = vec3(0,0.5,1);
                        content = combine(content, result(nd.xyz, nd.w, color));
                    }
                }
                else if(rnd < 0.2)
                {
                    //float height = height(tile);
                    float height = height_interpolated(vec2(tile)+0.5); // height at center
                    vec4 nd; MARCH(nd, tile, CYLINDER_Z, ray_pos_orig-vec3(vec2(tile.xy),height), ray_dir_orig, tmin, tmax);
                    if(nd.w > tmin && nd.w < tmax)
                    {
                        vec3 color = vec3(1);
                        content = combine(content, result(nd.xyz, nd.w, color));
                    }
                }
                else if(rnd < 0.3)
                {
                    //float height = height(tile);
                    float height = height_interpolated(vec2(tile)+0.5); // height at center
                    vec4 nd; MARCH(nd, tile, PLANT, ray_pos_orig-vec3(vec2(tile.xy),height), ray_dir_orig, tmin, tmax);
                    if(nd.w > tmin && nd.w < tmax)
                    {
                        //vec3 dst = ray_pos_orig-vec3(vec2(tile.xy),2)-0.5+ray_dir_orig*q.w;
                        vec3 color = vec3(1);
                        content = combine(content, result(nd.xyz, nd.w, color));
                    }
                }

                else if(rnd < 0.4)
                {
                    //float height = height(tile);
                    float height = height_interpolated(vec2(tile)+0.5); // height at center
                    vec4 nd; MARCH(nd, tile, BOX, ray_pos_orig-vec3(vec2(tile.xy),height), ray_dir_orig, tmin, tmax);
                    if(nd.w > tmin && nd.w < tmax)
                    {
                        //vec3 dst = ray_pos_orig-vec3(vec2(tile.xy),2)-0.5+ray_dir_orig*q.w;
                        vec3 color = vec3(1,0.01,0.01);
                        content = combine(content, result(nd.xyz, nd.w, color));
                    }
                }

                if(tmin > 0.0) // XXX WORKAROUND required when using voxel walls: at first step tmin is at 0 (or would be negative) XXX
                {
                }
            }
        }

        if(content.dist < tmax)
            return content;

        // update state
        nearest = nearest_next;
        tile = tile_next;
        side_dist = side_dist_next;
    }

    return content;
}

void mainImage(out vec4 fragColor, in vec2 I)
{
    bool demo = all(lessThan(iMouse.xy, vec2(10.0)));
    vec2 R = iResolution.xy;
    I = (I + I - R) / R.y; // concise pixel-position mapping thanks to Fabrice
    float yaw = 2.0 * pi * float(iMouse.x) / float(R.x);
    float pitch = pi - pi / 2.0 * float(iMouse.y) / float(R.y);
    //float pitch = pi - pi * float(iMouse.y) / float(R.y);
    yaw = !demo ? yaw : 2.0 * pi * fract(iTime * 0.01);
    //pitch = !demo ? pitch : 1.4 * pi/2.0; // circle flight demo
    pitch = !demo ? pitch : pi/2.0; // hover camera demo

    vec3 ray_pos = vec3(0.0, 0.0, -10.0);
    vec3 ray_dir = vec3(I.x, I.y, 2.0);
    ray_dir = normalize(ray_dir);

    mat3 M = yaw_pitch_roll(yaw, pitch, 0.0);
    ray_pos = M * ray_pos;
    ray_dir = M * ray_dir;

    ray_pos.z = max(ray_pos.z, 1.5+height_interpolated(ray_pos.xy));

    result res = trace(ray_pos, ray_dir);
    vec3 color = res.color;

    vec3 skycolor = mix(vec3(0.2,0.4,0.8),vec3(0,0,1),abs(ray_dir.z));

    bool lighttype = true;
    //vec3 sun_dir = lighttype ? normalize(vec3(3,2,1)) : vec3(0);
    vec3 sun_dir = lighttype ? normalize(vec3(5.0*vec2(cos(iTime/10.0),sin(iTime/10.0)),1)) : vec3(0);
    float dim = lighttype ? 1.0-pow(max(0.0, dot(M * vec3(0,0,1), sun_dir)), 4.0) : 1.0; // reduce brightness when looking towards sun to make sunlight seem brighter
    if(res.dist < DIST_MAX)
    {
        res.normal *= dot(res.normal, ray_dir) < 0.0 ? +1.0 : -1.0; // repair front-back for thin surfaces

        vec3 dst = ray_pos + ray_dir * res.dist;
        float light = 0.0;
        vec3 light_dir = vec3(0);
        if(lighttype) // directional light
        {
            light_dir = sun_dir;
            light = 2.0;
#ifdef USE_SHADOWS
            light *= trace(dst+res.normal*0.001, light_dir).dist < DIST_MAX ? 0.0 : 1.0;
#endif
        }
        else // point light
        {
            light = 50.0;
            //vec3 light_pos = vec3(0,0,5);
            vec3 light_pos = vec3(5.0*vec2(cos(-iTime/5.0),sin(-iTime/5.0)),5);
            vec3 light_diff = light_pos - dst;
            float light_dist = length(light_diff);
            light_dir = light_diff / light_dist;
#ifdef USE_SHADOWS
            light *= trace(dst+res.normal*0.001, light_dir).dist < light_dist ? 0.0 : 1.0 / (light_dist * light_dist);
#endif
        }

        float brightness = light * max(0.0, dot(res.normal, light_dir));
        vec3 diffuse = vec3(brightness);
        float ambient = 0.1;

        //color *= (0.5 + 0.5 * result.xyz); // visualize normals
        color *= (diffuse + ambient); // apply light
        //color = vec3(fract(result.w));

        if(brightness > 0.0)
        {
            float specular = pow(max(0.0, dot(res.normal, normalize(-ray_dir + light_dir))), 250.0);
            color += specular;
        }

        color = mix(skycolor, color, exp(-pow(distance(ray_pos.xy,dst.xy)/float(VISION_LIMIT), 2.0))); // distance fog (but not vertically)
    }
    else // sky
    {
        color = skycolor;
        if(true)
        {
            float d = max(0.0, dot(ray_dir, sun_dir));
            float sun = 50.0*smoothstep(0.999, 1.000, d) + exp(-pow((1.0-d)*1000.0, 2.0)); // sun with halo
            color += sun;
        }
    }
    //color *= dim;
    color = tanh(color); // roll-off / soft-clamp overly bright colors
    color = sqrt(color); // approximate gamma
    fragColor = vec4(color, 1.0);
}
